CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE layer_kind AS ENUM ('demographics', 'transport', 'poi', 'land_use', 'environmental_risk', 'utilities');
CREATE TYPE analysis_status AS ENUM ('queued', 'running', 'succeeded', 'failed', 'cancelled');
CREATE TABLE study_area (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL UNIQUE, scope TEXT NOT NULL CHECK (scope IN ('state', 'country', 'city', 'custom')), boundary geometry(MultiPolygon, 4326), distance_strategy TEXT NOT NULL DEFAULT 'geodesic_or_local_projection', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE data_layer (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), study_area_id UUID NOT NULL REFERENCES study_area(id), kind layer_kind NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE layer_version (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), layer_id UUID NOT NULL REFERENCES data_layer(id), version INTEGER NOT NULL CHECK (version > 0), source_name TEXT NOT NULL, source_license TEXT, source_crs TEXT NOT NULL, normalized_crs TEXT NOT NULL DEFAULT 'EPSG:4326', source_uri TEXT, quality_report JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (layer_id, version));
CREATE TABLE spatial_feature (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), layer_version_id UUID NOT NULL REFERENCES layer_version(id), source_feature_id TEXT, properties JSONB NOT NULL DEFAULT '{}'::jsonb, geom geometry(Geometry, 4326) NOT NULL);
CREATE INDEX spatial_feature_geom_gix ON spatial_feature USING GIST (geom);
CREATE TABLE score_config (id TEXT NOT NULL, version INTEGER NOT NULL CHECK (version > 0), target_use_case TEXT NOT NULL, factors JSONB NOT NULL, constraints JSONB NOT NULL DEFAULT '[]'::jsonb, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (id, version));
CREATE TABLE candidate_site (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), study_area_id UUID NOT NULL REFERENCES study_area(id), name TEXT NOT NULL, geom geometry(Point, 4326) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX candidate_site_geom_gix ON candidate_site USING GIST (geom);
CREATE TABLE analysis_run (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), study_area_id UUID NOT NULL REFERENCES study_area(id), score_config_id TEXT NOT NULL, score_config_version INTEGER NOT NULL, input_manifest JSONB NOT NULL, status analysis_status NOT NULL DEFAULT 'queued', algorithm_version TEXT NOT NULL, started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY (score_config_id, score_config_version) REFERENCES score_config(id, version));
CREATE TABLE site_score (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), analysis_run_id UUID NOT NULL REFERENCES analysis_run(id), candidate_site_id UUID NOT NULL REFERENCES candidate_site(id), score NUMERIC(5, 2) NOT NULL CHECK (score >= 0 AND score <= 100), eligibility TEXT NOT NULL, breakdown JSONB NOT NULL, UNIQUE (analysis_run_id, candidate_site_id));
CREATE TABLE analysis_cell (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), analysis_run_id UUID NOT NULL REFERENCES analysis_run(id), h3_index TEXT NOT NULL, score NUMERIC(5, 2) CHECK (score >= 0 AND score <= 100), cluster_type TEXT, geom geometry(Polygon, 4326) NOT NULL, UNIQUE (analysis_run_id, h3_index));
CREATE INDEX analysis_cell_geom_gix ON analysis_cell USING GIST (geom);
